mapper.select:
SELECT cbr.id, cbr.user_id, u.username, u.nickname, cbr.behavior_type, cbr.behavior_name, cbr.behavior_value, cbr.carbon_reduction, cbr.points, cbr.description, cbr.proof_image, cbr.audit_status, CASE cbr.audit_status WHEN 0 THEN '待审核' WHEN 1 THEN '审核通过' WHEN 2 THEN '审核拒绝' END AS audit_status_text, cbr.audit_user_id, au.username AS audit_username, cbr.audit_time, cbr.audit_remark, cbr.create_time FROM carbon_behavior_record cbr LEFT JOIN user u ON cbr.user_id = u.id LEFT JOIN user au ON cbr.audit_user_id = au.id WHERE 1=1
AND cbr.user_id = #{userId}
AND cbr.behavior_type = #{behaviorType}
AND cbr.audit_status = #{auditStatus}
AND cbr.create_time >= #{startTime}
AND cbr.create_time <= #{endTime}
ORDER BY cbr.create_time DESC

SELECT cbr.id, cbr.user_id, u.username, u.nickname, cbr.behavior_type, cbr.behavior_name, cbr.behavior_value, cbr.carbon_reduction, cbr.points, cbr.description, cbr.proof_image, cbr.audit_status, CASE cbr.audit_status WHEN 0 THEN '待审核' WHEN 1 THEN '审核通过' WHEN 2 THEN '审核拒绝' END AS audit_status_text, cbr.create_time FROM carbon_behavior_record cbr LEFT JOIN user u ON cbr.user_id = u.id WHERE cbr.audit_status = 0
AND cbr.user_id = #{userId}
AND cbr.behavior_type = #{behaviorType}
AND cbr.create_time >= #{startTime}
AND cbr.create_time <= #{endTime}
ORDER BY cbr.create_time ASC

SELECT cbr.behavior_type AS behaviorType, cbr.behavior_name AS behaviorName, COUNT(*) AS count, SUM(cbr.carbon_reduction) AS carbonReduction, SUM(cbr.points) AS points FROM carbon_behavior_record cbr WHERE cbr.audit_status = 1
AND cbr.user_id = #{userId}
AND cbr.create_time >= #{startTime}
AND cbr.create_time <= #{endTime}
GROUP BY cbr.behavior_type, cbr.behavior_name ORDER BY count DESC
